const APP_VERSION='0.3.1';
const DATA_SCHEMA_VERSION=1;
const CACHE_KEY='mi_cartera_cloud_cache_v1';
const SESSION_KEY='mi_cartera_supabase_session_v1';
const THEME_KEY='mi_cartera_theme';
const cfg=window.MI_CARTERA_CONFIG?.cloud||{};
const SUPABASE_URL=(cfg.url||'').replace(/\/$/,'');
const SUPABASE_KEY=cfg.publishableKey||cfg.anonKey||'';

const ENTITY={
  'BBVA':{code:'BBVA',color:'#004481',fundColor:'#004481'},
  'Bankinter':{code:'BANKINTER',color:'#FF8D30',fundColor:'#FF8D30'},
  'Trade Republic':{code:'TRADE_REPUBLIC',color:'#111111',fundColor:'#343434'},
  'MyInvestor':{code:'MYINVESTOR',color:'#171717',fundColor:'#d51c78'},
  'DEGIRO':{code:'DEGIRO',color:'#111111',fundColor:'#28a9e0'},
  'Kutxabank':{code:'KUTXABANK',color:'#111111',fundColor:'#c82127'}
};
const CODE_TO_ENTITY=Object.fromEntries(Object.entries(ENTITY).map(([name,v])=>[v.code,name]));
const LOGOS={
 'BBVA':'data:image/png;base64,',
 'Bankinter':'data:image/png;base64,',
 'Trade Republic':'data:image/png;base64,',
 'MyInvestor':'data:image/png;base64,',
 'DEGIRO':'data:image/png;base64,',
 'Kutxabank':'data:image/png;base64,'
};

let cloudAccounts=[];
let navHistory={};
let session=null;
let state={positions:[],operations:[],funds:{},group:'entity',opFilter:'all',lastValue:null,lastNavUpdate:null,updatedAt:null};

const eur=n=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number.isFinite(+n)?+n:0);
const pct=n=>n===null||n===undefined||!Number.isFinite(+n)?'—':((+n)>=0?'+':'')+(+n).toFixed(2).replace('.',',')+' %';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const posValue=p=>(+p.shares||0)*(+p.nav||0);
const meta=p=>state.funds?.[p.isin]||{name:p.isin,theme:'Sin clasificar',manager:'—',currency:'EUR'};
const total=()=>state.positions.reduce((a,p)=>a+posValue(p),0);
function weightedYtd(items){const valid=items.filter(p=>Number.isFinite(p.ytd));const v=valid.reduce((a,p)=>a+posValue(p),0);return v?valid.reduce((a,p)=>a+posValue(p)*p.ytd,0)/v:null}

function entityWordmark(name){
 const cls={'BBVA':'logo-bbva','Bankinter':'logo-bankinter','Trade Republic':'logo-trade-republic','MyInvestor':'logo-myinvestor','DEGIRO':'logo-degiro','Kutxabank':'logo-kutxabank'}[name]||'';
 const src=LOGOS[name];
 return src?`<img class="brand-logo-img ${cls}" alt="${esc(name)}" src="${src}">`:`<span>${esc(name)}</span>`;
}

function loadCache(){try{const x=JSON.parse(localStorage.getItem(CACHE_KEY)||'null');if(x&&Array.isArray(x.positions)){state={...state,...x};return true}}catch{}return false}
function saveCache(){state.updatedAt=new Date().toISOString();localStorage.setItem(CACHE_KEY,JSON.stringify(state))}
function loadSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
function saveSession(s){session=s;if(s)localStorage.setItem(SESSION_KEY,JSON.stringify(s));else localStorage.removeItem(SESSION_KEY)}

function setCloudStatus(text,kind=''){const el=document.getElementById('cloudStatus');if(el)el.textContent=text;const b=document.getElementById('syncBadge');if(b){b.textContent=text;b.dataset.kind=kind}}
function setAuthMessage(text,isError=false){const el=document.getElementById('authMessage');if(el){el.textContent=text||'';el.classList.toggle('metric-negative',!!isError)}}
function showAuth(){document.getElementById('authGate')?.classList.remove('hidden');document.getElementById('app')?.classList.add('auth-hidden')}
function showApp(){document.getElementById('authGate')?.classList.add('hidden');document.getElementById('app')?.classList.remove('auth-hidden');const email=session?.user?.email||'';const u=document.getElementById('signedUser');if(u)u.textContent=email;const b=document.querySelector('.brand');if(b)b.textContent=session?.user?.user_metadata?.display_name||'Mi Cartera'}

async function authFetch(path,options={}){
 const res=await fetch(SUPABASE_URL+path,{...options,headers:{'apikey':SUPABASE_KEY,'Content-Type':'application/json',...(options.headers||{})}});
 const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}
 if(!res.ok){const msg=data?.msg||data?.message||data?.error_description||data?.error||`HTTP ${res.status}`;throw new Error(msg)}return data;
}
async function signIn(email,password){
 const data=await authFetch('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});
 data.expires_at=Math.floor(Date.now()/1000)+(data.expires_in||3600);saveSession(data);return data;
}
async function refreshSession(){
 if(!session?.refresh_token)throw new Error('Sesión caducada');
 const data=await authFetch('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})});
 data.expires_at=Math.floor(Date.now()/1000)+(data.expires_in||3600);saveSession(data);return data;
}
async function ensureSession(){
 session=loadSession();if(!session)return false;
 if((session.expires_at||0)<Math.floor(Date.now()/1000)+90){try{await refreshSession()}catch{saveSession(null);session=null;return false}}
 return true;
}
async function signOut(){
 try{if(session?.access_token)await authFetch('/auth/v1/logout',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`}})}catch{}
 saveSession(null);session=null;showAuth();setAuthMessage('Sesión cerrada.');
}

async function rest(path,options={},retry=true){
 if(!session?.access_token)throw new Error('No hay sesión iniciada');
 const headers={'apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`,'Content-Type':'application/json',...(options.headers||{})};
 const res=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...options,headers});
 if(res.status===401&&retry){await refreshSession();return rest(path,options,false)}
 const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}
 if(!res.ok){const msg=data?.message||data?.hint||data?.details||`HTTP ${res.status}`;throw new Error(msg)}return data;
}
const select=(table,query='')=>rest(`${table}${query?'?'+query:''}`);
const insert=(table,body)=>rest(table,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(body)});
const patch=(table,query,body)=>rest(`${table}?${query}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(body)});
const rpc=(name,body)=>rest(`rpc/${name}`,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(body)});

async function edge(name,body,retry=true){
 if(!session?.access_token)throw new Error('No hay sesión iniciada');
 const res=await fetch(`${SUPABASE_URL}/functions/v1/${name}`,{method:'POST',headers:{'apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(body||{})});
 if(res.status===401&&retry){await refreshSession();return edge(name,body,false)}
 const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}
 if(!res.ok||data?.ok===false){const msg=data?.details||data?.error||data?.message||`HTTP ${res.status}`;throw new Error(msg)}
 return data;
}
function validIsin(isin){
 isin=String(isin||'').trim().toUpperCase();if(!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin))return false;
 const expanded=[...isin].map(c=>/[A-Z]/.test(c)?String(c.charCodeAt(0)-55):c).join('');let sum=0,dbl=false;
 for(let i=expanded.length-1;i>=0;i--){let n=+expanded[i];if(dbl){n*=2;if(n>9)n-=9}sum+=n;dbl=!dbl}return sum%10===0;
}
async function resolveFund(isin,includeHistory=false){
 isin=String(isin||'').trim().toUpperCase();if(!validIsin(isin))throw new Error('ISIN no válido');
 const result=await edge('resolve-fund',{isin,include_history:!!includeHistory});
 const f=result?.fund||{};const old=state.funds?.[isin]||{};const latest=result?.latest_nav||old.latest_nav||null;
 state.funds[isin]={...old,...f,data_provider:f.provider||old.data_provider,provider_symbol:f.provider_symbol||old.provider_symbol,metadata_source:f.metadata_source||old.metadata_source,theme:(old.theme&&old.theme!=='Sin clasificar')?old.theme:(f.category||old.category||'Sin clasificar'),latest_nav:latest,sources:result?.sources||old.sources||null};
 saveCache();return result;
}
async function ensureResolvedFund(isin,includeHistory=false){
 try{return await resolveFund(isin,includeHistory)}catch(err){const existing=state.funds?.[isin];await ensureFund(isin,existing?.name||isin,'Sin clasificar');throw err}
}

function nearestReturn(series,targetDate){
 if(!series?.length)return null;const latest=series[series.length-1];const target=targetDate.getTime();let base=null;for(const row of series){if(new Date(row.nav_date+'T00:00:00Z').getTime()>=target){base=row;break}}if(!base||!+base.nav||!+latest.nav)return null;return (+latest.nav/+base.nav-1)*100;
}
function buildPositions(operations,accounts,funds,navRows){
 const accountMap=Object.fromEntries(accounts.map(a=>[a.id,a]));
 const byIsin={};for(const n of navRows){(byIsin[n.isin]??=[]).push(n)}for(const arr of Object.values(byIsin))arr.sort((a,b)=>a.nav_date.localeCompare(b.nav_date));
 navHistory=byIsin;
 const groups=new Map();
 const completed=operations.filter(o=>o.status==='completed'&&o.shares_delta!==null);
 completed.sort((a,b)=>(a.operation_date||'').localeCompare(b.operation_date||'')||(a.created_at||'').localeCompare(b.created_at||''));
 for(const o of completed){
   const acc=accountMap[o.account_id];if(!acc)continue;const key=o.account_id+'|'+o.isin;let g=groups.get(key);if(!g)g={id:key,accountId:o.account_id,isin:o.isin,entity:CODE_TO_ENTITY[acc.institution_code]||acc.institution_code,shares:0,invested:0,start:o.operation_date,latestOpNav:null,latestOpDate:null};
   const delta=+o.shares_delta||0;const amount=+o.amount||0;
   if(delta>0){g.invested+=amount>0?amount:Math.abs(delta)*(+o.nav||0)}else if(delta<0&&g.shares>0){const ratio=Math.min(1,Math.abs(delta)/g.shares);g.invested=Math.max(0,g.invested*(1-ratio))}
   g.shares+=delta;if(+o.nav>0&&(!g.latestOpDate||o.operation_date>=g.latestOpDate)){g.latestOpNav=+o.nav;g.latestOpDate=o.operation_date}if(o.operation_date<g.start)g.start=o.operation_date;groups.set(key,g);
 }
 const today=new Date();const m1=new Date(today);m1.setMonth(m1.getMonth()-1);const m3=new Date(today);m3.setMonth(m3.getMonth()-3);const ytd=new Date(Date.UTC(today.getUTCFullYear(),0,1));
 const result=[];
 for(const g of groups.values()){
   if(Math.abs(g.shares)<1e-10)continue;const series=byIsin[g.isin]||[];const latest=series.at(-1);const prev=series.at(-2)||latest;const onlineIsCurrent=latest&&(!g.latestOpDate||latest.nav_date>=g.latestOpDate);const nav=onlineIsCurrent?+latest.nav:(g.latestOpNav||(+latest?.nav||0));const prevNav=onlineIsCurrent?(prev?+prev.nav:nav):(+latest?.nav||nav);
   result.push({...g,nav,prevNav,navDate:onlineIsCurrent?latest?.nav_date:(g.latestOpDate||latest?.nav_date||null),navStatus:onlineIsCurrent?'online':'provisional',m1:nearestReturn(series,m1),m3:nearestReturn(series,m3),ytd:nearestReturn(series,ytd)});
 }
 return result;
}

function mapOperations(ops,transfers,accounts){
 const accountMap=Object.fromEntries(accounts.map(a=>[a.id,a]));
 const out=[];
 const typeLabel={initial:'Posición inicial',buy:'Compra',contribution:'Aportación',sale:'Venta',redemption:'Reembolso',adjustment:'Ajuste'};
 for(const o of ops){if(['transfer_in','transfer_out'].includes(o.operation_type))continue;const acc=accountMap[o.account_id];out.push({id:o.id,type:typeLabel[o.operation_type]||o.operation_type,operationType:o.operation_type,date:o.operation_date,isin:o.isin,entity:CODE_TO_ENTITY[acc?.institution_code]||acc?.institution_code||'—',amount:+o.amount||0,shares:o.shares_delta===null?null:Math.abs(+o.shares_delta||0),sharesDelta:o.shares_delta===null?null:+o.shares_delta,nav:o.nav===null?null:+o.nav,fees:+o.fees||0,externalCashflow:+o.external_cashflow||0,status:o.status==='completed'?'done':o.status})}
 for(const t of transfers){const a=accountMap[t.from_account_id],b=accountMap[t.to_account_id];out.push({id:t.id,type:'Traspaso',date:t.request_date,settlementDate:t.settlement_date,from:t.from_isin,fromEntity:CODE_TO_ENTITY[a?.institution_code]||a?.institution_code||'—',to:t.to_isin,toEntity:CODE_TO_ENTITY[b?.institution_code]||b?.institution_code||'—',amount:+t.amount||0,fromShares:t.shares_out===null?null:+t.shares_out,toShares:t.shares_in===null?null:+t.shares_in,status:t.status==='completed'?'done':t.status})}
 out.sort((a,b)=>(b.date||'').localeCompare(a.date||''));return out;
}

async function syncFromCloud(showNotice=false){
 setCloudStatus('Sincronizando…');
 try{
   const since=new Date();since.setFullYear(since.getFullYear()-3);const sinceISO=since.toISOString().slice(0,10);
   const [accounts,ops,transfers,funds,navs,profile]=await Promise.all([
     select('accounts','select=id,institution_code,account_name,active,created_at&order=created_at'),
     select('operations','select=id,account_id,isin,operation_type,operation_date,amount,shares_delta,nav,fees,external_cashflow,status,transfer_id,notes,created_at,updated_at&order=operation_date.desc,created_at.desc'),
     select('transfers','select=id,from_account_id,from_isin,to_account_id,to_isin,request_date,settlement_date,amount,shares_out,shares_in,nav_out,nav_in,status,notes,created_at,updated_at&order=request_date.desc,created_at.desc'),
     select('funds','select=isin,name,manager,currency,theme,subtheme,benchmark,active,category,category_source,category_fetched_at,data_provider,provider_symbol,metadata_source,metadata_fetched_at'),
     select('fund_navs',`select=isin,nav_date,nav,currency,source,fetched_at&nav_date=gte.${sinceISO}&order=nav_date.asc&limit=10000`),
     select('profiles','select=display_name&limit=1')
   ]);
   cloudAccounts=accounts||[];const oldTotal=total();state.funds={};for(const f of funds||[])state.funds[f.isin]={...f,theme:(f.theme&&f.theme!=='Sin clasificar')?f.theme:(f.category||'Sin clasificar')};for(const n of navs||[]){const f=state.funds[n.isin];if(!f)continue;if(!f.latest_nav||n.nav_date>f.latest_nav.date)f.latest_nav={date:n.nav_date,nav:+n.nav,currency:n.currency||f.currency||'EUR',source:n.source||'Supabase',fetched_at:n.fetched_at||null}}state.positions=buildPositions(ops||[],accounts||[],funds||[],navs||[]);state.operations=mapOperations(ops||[],transfers||[],accounts||[]);state.lastValue=oldTotal||state.lastValue;state.lastNavUpdate=(navs||[]).reduce((m,n)=>!m||n.nav_date>m?n.nav_date:m,null);saveCache();renderAll();
   const name=profile?.[0]?.display_name;if(name){const b=document.querySelector('.brand');if(b)b.textContent=name}
   setCloudStatus('Sincronizado con Supabase','ok');if(showNotice)alert('Datos sincronizados con Supabase.');return true;
 }catch(err){console.error(err);setCloudStatus('Sin conexión · mostrando última copia local','warn');if(showNotice)alert('No se pudo sincronizar: '+err.message);return false}
}

async function ensureFund(isin,name,theme){
 const existing=state.funds?.[isin];if(existing)return existing;const rows=await rpc('ensure_fund',{p_isin:isin,p_name:name||isin,p_theme:theme||'Sin clasificar',p_currency:'EUR'});return Array.isArray(rows)?rows[0]:rows;
}
async function ensureAccount(entity){
 const code=ENTITY[entity]?.code||entity;let a=cloudAccounts.find(x=>x.institution_code===code&&x.active!==false);if(a)return a;
 const rows=await insert('accounts',{institution_code:code,account_name:'Principal',active:true});a=rows?.[0];if(!a)throw new Error('No se pudo crear la cuenta de '+entity);cloudAccounts.push(a);return a;
}

function renderHome(){
 const t=total(),y=weightedYtd(state.positions);document.getElementById('totalValue').textContent=eur(t);const yt=document.getElementById('totalYtd');yt.textContent=(y===null?'YTD —':pct(y)+' YTD');yt.className=y===null?'muted':(y>=0?'metric-positive':'metric-negative');
 const diff=state.lastValue===null?0:t-state.lastValue;document.getElementById('sinceUpdate').innerHTML=state.lastValue===null?'—':`<span class="${diff>=0?'metric-positive':'metric-negative'}">${diff>=0?'+':''}${eur(diff)}</span>`;document.getElementById('lastUpdate').textContent=state.lastNavUpdate?`VL hasta ${new Date(state.lastNavUpdate+'T00:00:00').toLocaleDateString('es-ES')}`:'Sin VL online · valoración provisional';
 const groups={};state.positions.forEach(p=>(groups[p.entity]??=[]).push(p));
 document.getElementById('entitySummary').innerHTML=Object.entries(groups).map(([e,ps])=>{const v=ps.reduce((a,p)=>a+posValue(p),0),yy=weightedYtd(ps);return `<article class="entity-card" data-entity="${esc(e)}"><div class="entity-main"><div><div class="entity-name">${entityWordmark(e)}</div><div class="entity-sub">${ps.length} ${ps.length===1?'fondo':'fondos'}</div></div><div class="entity-value">${eur(v)}<div class="entity-ytd ${yy===null?'muted':yy>=0?'metric-positive':'metric-negative'}">${yy===null?'YTD —':pct(yy)+' YTD'}</div></div></div><div class="entity-detail">${ps.map(p=>{const ec=ENTITY[p.entity]||{fundColor:'#64748b'};return `<div class="fund-row" data-pos="${esc(p.id)}" style="background:color-mix(in srgb, ${ec.fundColor} 11%, var(--panel));border-left:4px solid ${ec.fundColor}"><div><div class="fund-name">${esc(meta(p).name)}</div><div class="fund-meta">${esc(p.isin)} · ${esc(meta(p).theme)}</div></div><div class="fund-value">${eur(posValue(p))}<div class="trend"><span class="${p.nav>=p.prevNav?'arrow up':'arrow down'}">${p.nav>=p.prevNav?'↑':'↓'}</span> ${p.ytd===null?'YTD —':pct(p.ytd)+' YTD'}</div></div></div>`}).join('')}</div></article>`}).join('')||'<div class="notice">Todavía no hay posiciones. Pulsa <strong>+ Operación</strong> para introducir la primera.</div>';
 document.querySelectorAll('.entity-main').forEach(x=>x.onclick=()=>x.closest('.entity-card').classList.toggle('open'));document.querySelectorAll('.fund-row').forEach(x=>x.onclick=e=>{e.stopPropagation();openDetail(x.dataset.pos)});
}
function renderPositions(){
 const q=document.getElementById('positionSearch').value.trim().toLowerCase();const items=state.positions.filter(p=>meta(p).name.toLowerCase().includes(q)||p.isin.toLowerCase().includes(q));const groups={};items.forEach(p=>{const key=state.group==='entity'?p.entity:meta(p).theme;(groups[key]??=[]).push(p)});
 document.getElementById('positionsBody').innerHTML=Object.entries(groups).map(([g,ps])=>{const gv=ps.reduce((a,p)=>a+posValue(p),0);return `<section class="group-block"><div class="group-title ${state.group==='entity'?'bank-group-title':''}"><h3>${state.group==='entity'?entityWordmark(g):esc(g)}</h3><span>${eur(gv)}</span></div><div class="position-list">${ps.map(p=>{const m=meta(p),val=posValue(p),gain=val-p.invested,ret=p.invested?gain/p.invested*100:null,ec=ENTITY[p.entity]||{fundColor:'#64748b'};return `<article class="position-card" data-pos="${esc(p.id)}" style="background:color-mix(in srgb, ${ec.fundColor} 10%, var(--panel));border-left:4px solid ${ec.fundColor}"><div class="position-top"><div class="position-main"><div class="position-name">${esc(m.name)}</div><div class="position-isin">${esc(p.isin)} · ${esc(p.entity)} · ${esc(m.theme)}</div></div><div class="position-val">${eur(val)}</div></div><div class="position-result ${ret===null?'muted':ret>=0?'metric-positive':'metric-negative'}">Mi posición: ${gain>=0?'+':''}${eur(gain)} · ${pct(ret)}</div><div class="chips"><span class="chip">1M ${pct(p.m1)}</span><span class="chip">3M ${pct(p.m3)}</span><span class="chip">YTD ${pct(p.ytd)}</span></div>${p.navStatus==='provisional'?'<div class="pending-hint">VL provisional calculado desde la operación. Pendiente de fuente online.</div>':''}</article>`}).join('')}</div></section>`}).join('')||'<div class="notice">No hay posiciones que coincidan.</div>';
 document.querySelectorAll('.position-card').forEach(x=>x.onclick=()=>openDetail(x.dataset.pos));
}
function renderOps(){
 const arr=state.operations.filter(o=>state.opFilter==='all'||(state.opFilter==='transfer'&&o.type==='Traspaso')||(state.opFilter==='pending'&&o.status==='pending'));
 document.getElementById('opsList').innerHTML=arr.map(o=>{if(o.type==='Traspaso'){const pending=o.status==='pending';return `<article class="op-card ${pending?'pending-editable':''}" ${pending?`data-edit-op="${esc(o.id)}"`:''}><div class="op-head"><div><div class="op-type">Traspaso</div><div class="muted" style="font-size:12px">${esc(o.date)}</div>${pending?'<div class="pending-hint">Pulsa para completar los datos pendientes</div>':''}</div>${pending?'<div class="pending">⏸ Pendiente</div>':'<div class="metric-positive" style="font-size:12px">✓ Finalizado</div>'}</div><div class="op-flow"><div class="op-box"><strong>${entityWordmark(o.fromEntity)}</strong>${esc(meta({isin:o.from}).name)}<br><span class="muted">− ${eur(o.amount)}</span></div><div>→</div><div class="op-box"><strong>${entityWordmark(o.toEntity)}</strong>${esc(meta({isin:o.to}).name)}<br><span class="muted">+ ${eur(o.amount)}</span></div></div></article>`}return `<article class="op-card editable-operation" data-edit-basic="${esc(o.id)}"><div class="op-head"><div><div class="op-type">${esc(o.type)}</div><div class="muted" style="font-size:12px">${esc(o.date)}</div><div class="pending-hint">Pulsa para editar la operación</div></div><strong>${eur(o.amount)}</strong></div><div class="op-box" style="margin-top:9px"><strong>${entityWordmark(o.entity)}</strong>${esc(meta({isin:o.isin}).name)}</div></article>`}).join('')||'<div class="notice">No hay operaciones en este filtro.</div>';
 document.querySelectorAll('[data-edit-op]').forEach(card=>card.onclick=()=>openPendingTransfer(card.dataset.editOp));
 document.querySelectorAll('[data-edit-basic]').forEach(card=>card.onclick=()=>openBasicOperation(card.dataset.editBasic));
}
function renderAnalysis(){const groups={};state.positions.forEach(p=>groups[meta(p).theme]=(groups[meta(p).theme]||0)+posValue(p));const t=total();document.getElementById('themeBars').innerHTML=t?Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="barrow"><div>${esc(k)}</div><div class="bartrack"><div class="barfill" style="width:${v/t*100}%;color:#334155"></div></div><div class="barval">${(v/t*100).toFixed(1).replace('.',',')}%</div></div>`).join(''):'<div class="notice">Sin posiciones.</div>'}
function renderAll(){renderHome();renderPositions();renderOps();renderAnalysis()}

function rangeDate(range){const d=new Date();if(range==='M1')d.setMonth(d.getMonth()-1);else if(range==='M3')d.setMonth(d.getMonth()-3);else if(range==='M6')d.setMonth(d.getMonth()-6);else if(range==='Y1')d.setFullYear(d.getFullYear()-1);else if(range==='Y3')d.setFullYear(d.getFullYear()-3);else if(range==='YTD')return new Date(Date.UTC(d.getUTCFullYear(),0,1));else return new Date(0);return d}
function seriesFor(p,range){const rows=navHistory[p.isin]||[];const target=rangeDate(range).getTime();return rows.filter(r=>new Date(r.nav_date+'T00:00:00Z').getTime()>=target).map(r=>+r.nav)}
function drawChart(p,range){const c=document.getElementById('fundChart');if(!c)return;const data=seriesFor(p,range);const retEl=document.getElementById('rangeReturn');if(data.length<2){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);retEl.textContent='Sin histórico suficiente';return}const dpr=window.devicePixelRatio||1,w=c.clientWidth,h=220;c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const min=Math.min(...data),max=Math.max(...data),pad=16;ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue('--line').trim();ctx.lineWidth=1;for(let i=0;i<4;i++){const y=pad+(h-2*pad)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke()}ctx.strokeStyle=data.at(-1)>=data[0]?'#0a8f4f':'#c43232';ctx.lineWidth=2;ctx.beginPath();data.forEach((v,i)=>{const x=pad+(w-2*pad)*i/(data.length-1),y=h-pad-(v-min)/(max-min||1)*(h-2*pad);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();retEl.textContent=pct((data.at(-1)/data[0]-1)*100)}
function openDetail(id){const p=state.positions.find(x=>x.id===id);if(!p)return;const m=meta(p),val=posValue(p),gain=val-p.invested,ret=p.invested?gain/p.invested*100:null;document.getElementById('detailContent').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">${esc(p.entity)} · ${esc(m.theme)}</div><div class="drawer-title">${esc(m.name)}</div><div class="muted" style="font-size:12px;margin-top:4px">${esc(p.isin)}</div></div><button class="close" onclick="closeDetail()">×</button></div><div class="detail-kpis"><div class="kpi"><span>Valor actual</span><strong>${eur(val)}</strong></div><div class="kpi"><span>Mi posición</span><strong class="${ret===null?'':ret>=0?'metric-positive':'metric-negative'}">${pct(ret)}</strong></div><div class="kpi"><span>Participaciones</span><strong>${(+p.shares).toLocaleString('es-ES',{maximumFractionDigits:6})}</strong></div><div class="kpi"><span>VL</span><strong>${p.nav?Number(p.nav).toFixed(4).replace('.',',')+' €':'—'}</strong></div></div><div class="chart-wrap"><div style="display:flex;justify-content:space-between;align-items:end"><div><div class="eyebrow">Evolución del fondo</div><strong id="rangeReturn">—</strong></div><div class="muted" style="font-size:11px">Histórico guardado en Supabase</div></div><canvas id="fundChart"></canvas><div class="rangebar" id="rangebar"><button data-range="M1">1M</button><button class="active" data-range="M3">3M</button><button data-range="M6">6M</button><button data-range="YTD">YTD</button><button data-range="Y1">1A</button><button data-range="Y3">3A</button><button data-range="MAX">Máx</button></div></div><div class="notice" style="margin-top:12px"><strong>Rentabilidad del fondo:</strong> 1M ${pct(p.m1)} · 3M ${pct(p.m3)} · YTD ${pct(p.ytd)}<br><strong>Resultado de mi inversión:</strong> ${gain>=0?'+':''}${eur(gain)} · ${pct(ret)}${p.navStatus==='provisional'?'<br><strong>Nota:</strong> valoración provisional hasta disponer de VL online.':''}</div>`;document.getElementById('detailBackdrop').classList.add('open');document.querySelectorAll('#rangebar button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#rangebar button').forEach(x=>x.classList.remove('active'));b.classList.add('active');drawChart(p,b.dataset.range)});setTimeout(()=>drawChart(p,'M3'),30)}
function closeDetail(){document.getElementById('detailBackdrop').classList.remove('open')}
window.closeDetail=closeDetail;

function navigate(page){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('newOpFab').style.display=page==='operations'||page==='positions'?'block':'none';if(page==='positions')renderPositions();if(page==='operations')renderOps();if(page==='analysis')renderAnalysis()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));

function entityOptions(){return Object.keys(ENTITY).map(e=>`<option>${esc(e)}</option>`).join('')}
function todayISO(){return new Date().toISOString().slice(0,10)}
function openNewOp(){document.getElementById('opContent').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">Operaciones</div><div class="drawer-title">Nueva operación</div></div><button class="close" onclick="closeOp()">×</button></div><div class="segmented" id="typeSeg" style="margin:16px 0"><button class="active" data-type="Posición inicial">Inicial</button><button data-type="Compra">Compra</button><button data-type="Aportación">Aportación</button><button data-type="Reembolso">Reembolso</button><button data-type="Venta">Venta</button><button data-type="Traspaso">Traspaso</button></div><div id="dynamicForm"></div>`;document.getElementById('opBackdrop').classList.add('open');document.querySelectorAll('#typeSeg button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#typeSeg button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderOpForm(b.dataset.type)});renderOpForm('Posición inicial')}
function closeOp(){document.getElementById('opBackdrop').classList.remove('open')}
window.closeOp=closeOp;
function renderOpForm(type){const transfer=type==='Traspaso';document.getElementById('dynamicForm').innerHTML=transfer?`<div class="form-grid"><div class="field"><label>Entidad origen</label><select id="fFromEntity">${entityOptions()}</select></div><div class="field"><label>ISIN origen</label><input id="fFromIsin" placeholder="LU..." /></div><div class="field"><label>Entidad destino</label><select id="fToEntity">${entityOptions()}</select></div><div class="field"><label>ISIN destino</label><input id="fToIsin" placeholder="LU..." /></div><div class="field"><label>Fecha</label><input id="fDate" type="date" value="${todayISO()}" /></div><div class="field"><label>Importe</label><input id="fAmount" type="number" inputmode="decimal" step="any" /></div><div class="field"><label>Participaciones salida (opcional)</label><input id="fFromShares" type="number" inputmode="decimal" step="any" /></div><div class="field"><label>Participaciones entrada (opcional)</label><input id="fToShares" type="number" inputmode="decimal" step="any" /></div><div class="notice">Si faltan participaciones se guardará como <strong>pendiente</strong>. Podrás abrirlo después y completarlo.</div></div><div class="form-actions"><button class="btn" onclick="closeOp()">Cancelar</button><button class="btn primary" onclick="saveTransfer()">Guardar traspaso</button></div>`:`<div class="form-grid"><div class="field"><label>Entidad</label><select id="fEntity">${entityOptions()}</select></div><div class="field"><label>ISIN</label><input id="fIsin" placeholder="LU..." maxlength="12" autocapitalize="characters" oninput="lookupIsin(this.value)" /></div><div class="notice" id="isinInfo">Introduce un ISIN válido de 12 caracteres. La identificación se realizará automáticamente.</div><div class="field"><label>Nombre del fondo</label><input id="fFundName" placeholder="Se cargará automáticamente" readonly /></div><div class="field"><label>Categoría</label><input id="fCategory" placeholder="Se cargará desde la fuente si está disponible" readonly /></div><div class="field"><label>Gestora</label><input id="fManager" placeholder="Se cargará automáticamente" readonly /></div><div class="field"><label>Benchmark</label><input id="fBenchmark" placeholder="Sin datos" readonly /></div><div class="field"><label>Valor liquidativo actual</label><input id="fLatestNav" placeholder="Sin datos" readonly /></div><div class="field"><label>Fecha del valor liquidativo</label><input id="fLatestNavDate" placeholder="Sin datos" readonly /></div><div class="field"><label>Fuente del VL</label><input id="fNavSource" placeholder="Sin datos" readonly /></div><div class="field"><label>Fecha de la operación</label><input id="fDate" type="date" value="${todayISO()}" /></div><div class="field"><label>${['Venta','Reembolso'].includes(type)?'Importe recibido':'Dinero invertido'}</label><input id="fAmount" type="number" inputmode="decimal" step="any" /></div><div class="field"><label>Número de participaciones</label><input id="fShares" type="number" inputmode="decimal" step="any" /></div></div><div class="form-actions"><button class="btn" onclick="closeOp()">Cancelar</button><button class="btn primary" onclick="saveBasic('${type}')">Guardar</button></div>`}
let isinLookupTimer=null,isinLookupSeq=0;
function paintResolvedFund(isin,result=null){const m=state.funds?.[isin]||result?.fund;const latest=result?.latest_nav||m?.latest_nav||null;const info=document.getElementById('isinInfo');const n=document.getElementById('fFundName'),c=document.getElementById('fCategory'),g=document.getElementById('fManager'),b=document.getElementById('fBenchmark'),v=document.getElementById('fLatestNav'),d=document.getElementById('fLatestNavDate'),src=document.getElementById('fNavSource');if(!m)return;if(n)n.value=m.name||isin;if(c)c.value=m.category||'';if(g)g.value=m.manager||'';if(b)b.value=m.benchmark||'';if(v)v.value=latest&&Number.isFinite(+latest.nav)?new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:6}).format(+latest.nav)+' '+(latest.currency||m.currency||''):'';if(d)d.value=latest?.date?new Date(latest.date+'T00:00:00').toLocaleDateString('es-ES'):'';if(src)src.value=latest?.source||'';if(info)info.innerHTML=`<strong>${esc(m.name||isin)}</strong><br>Categoría: ${esc(m.category||'Sin datos')} · Divisa: ${esc(m.currency||'Sin datos')}${m.manager?`<br>Gestora: ${esc(m.manager)}`:''}${m.benchmark?`<br>Benchmark: ${esc(m.benchmark)}`:''}${latest?`<br>VL: ${esc(new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:6}).format(+latest.nav))} ${esc(latest.currency||m.currency||'')} · ${esc(new Date(latest.date+'T00:00:00').toLocaleDateString('es-ES'))} · ${esc(latest.source||'')}`:''}`;}
function lookupIsin(v){
 const seq=++isinLookupSeq;const isin=String(v||'').trim().toUpperCase();const info=document.getElementById('isinInfo');['fFundName','fCategory','fManager','fBenchmark','fLatestNav','fLatestNavDate','fNavSource'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});clearTimeout(isinLookupTimer);
 if(isin.length<12){if(info)info.textContent='Introduce un ISIN válido de 12 caracteres. La identificación se realizará automáticamente.';return}
 if(!validIsin(isin)){if(info)info.innerHTML='<strong>ISIN no válido.</strong> Revisa los 12 caracteres.';return}
 const cached=state.funds?.[isin];if(cached?.provider_symbol&&cached?.metadata_source&&cached?.category&&cached?.benchmark&&cached?.latest_nav){paintResolvedFund(isin);return}
 if(info)info.textContent='Buscando el fondo por ISIN…';
 isinLookupTimer=setTimeout(async()=>{try{const r=await resolveFund(isin,false);if(seq!==isinLookupSeq)return;paintResolvedFund(isin,r)}catch(err){if(seq!==isinLookupSeq)return;if(info)info.innerHTML=`No se pudo identificar automáticamente: ${esc(err.message)}. La operación podrá guardarse con metadatos pendientes.`}},350);
}
window.lookupIsin=lookupIsin;

async function saveBasic(type){
 try{const isin=document.getElementById('fIsin').value.trim().toUpperCase(),entity=document.getElementById('fEntity').value,amount=+document.getElementById('fAmount').value||0,shares=+document.getElementById('fShares').value||0,date=document.getElementById('fDate').value;if(!isin||!shares||!date)throw new Error('Introduce ISIN, fecha y participaciones.');if(!validIsin(isin))throw new Error('El ISIN no es válido.');let metadataWarning=null;try{await resolveFund(isin,true)}catch(err){metadataWarning=err.message;await ensureFund(isin,state.funds?.[isin]?.name||isin,'Sin clasificar')}const account=await ensureAccount(entity);const typeMap={'Posición inicial':'initial','Compra':'buy','Aportación':'contribution','Reembolso':'redemption','Venta':'sale'};const isOut=['Reembolso','Venta'].includes(type);const delta=isOut?-Math.abs(shares):Math.abs(shares);const nav=shares?amount/Math.abs(shares):null;await insert('operations',{account_id:account.id,isin,operation_type:typeMap[type],operation_date:date,amount,shares_delta:delta,nav,fees:0,external_cashflow:isOut?-amount:amount,status:'completed'});closeOp();await syncFromCloud();navigate('positions');if(metadataWarning)alert('Operación guardada. Los metadatos del fondo quedan pendientes: '+metadataWarning)}
 catch(err){alert('No se pudo guardar la operación: '+err.message)}
}
window.saveBasic=saveBasic;

async function saveTransfer(){
 try{const fromEntity=document.getElementById('fFromEntity').value,toEntity=document.getElementById('fToEntity').value,from=document.getElementById('fFromIsin').value.trim().toUpperCase(),to=document.getElementById('fToIsin').value.trim().toUpperCase(),date=document.getElementById('fDate').value,amount=+document.getElementById('fAmount').value||0,fromShares=+document.getElementById('fFromShares').value||null,toShares=+document.getElementById('fToShares').value||null;if(!from||!to||!date)throw new Error('Completa ISIN origen, ISIN destino y fecha.');if(!validIsin(from)||!validIsin(to))throw new Error('Revisa los ISIN de origen y destino.');try{await resolveFund(from,false)}catch{await ensureFund(from,state.funds[from]?.name||from,'Sin clasificar')}try{await resolveFund(to,false)}catch{await ensureFund(to,state.funds[to]?.name||to,'Sin clasificar')}const a=await ensureAccount(fromEntity),b=await ensureAccount(toEntity);const rows=await insert('transfers',{from_account_id:a.id,from_isin:from,to_account_id:b.id,to_isin:to,request_date:date,amount,shares_out:fromShares,shares_in:toShares,status:'pending'});const tr=rows?.[0];if(tr&&fromShares&&toShares)await rpc('complete_transfer',{p_transfer_id:tr.id,p_shares_out:fromShares,p_shares_in:toShares,p_settlement_date:date,p_nav_out:amount/fromShares||null,p_nav_in:amount/toShares||null});closeOp();await syncFromCloud();navigate('operations')}
 catch(err){alert('No se pudo guardar el traspaso: '+err.message)}
}
window.saveTransfer=saveTransfer;

function basicTypeOptions(current){const opts=['Posición inicial','Compra','Aportación','Venta','Reembolso'];return opts.map(x=>`<option${x===current?' selected':''}>${x}</option>`).join('')}
function openBasicOperation(id){
 const o=state.operations.find(x=>x.id===id&&x.type!=='Traspaso');if(!o)return;
 document.getElementById('opContent').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">Editar operación</div><div class="drawer-title">${esc(o.type)}</div></div><button class="close" onclick="closeOp()">×</button></div><div class="form-grid"><div class="field"><label>Tipo de operación</label><select id="fEditType">${basicTypeOptions(o.type)}</select></div><div class="field"><label>Entidad</label><select id="fEntity">${entityOptions()}</select></div><div class="field"><label>ISIN</label><input id="fIsin" value="${esc(o.isin)}" oninput="lookupIsin(this.value)" /></div><div class="notice" id="isinInfo"><strong>${esc(meta({isin:o.isin}).name)}</strong><br>Temática: ${esc(meta({isin:o.isin}).theme||'Sin clasificar')}</div><div class="field"><label>Fecha</label><input id="fDate" type="date" value="${esc(o.date)}" /></div><div class="field"><label>Importe</label><input id="fAmount" type="number" inputmode="decimal" step="any" value="${o.amount||''}" /></div><div class="field"><label>Número de participaciones</label><input id="fShares" type="number" inputmode="decimal" step="any" value="${o.shares??''}" /></div><div class="notice">Puedes corregir la entidad, ISIN, fecha, importe, participaciones o tipo de operación. La posición se recalculará desde Supabase al guardar.</div></div><div class="form-actions"><button class="btn" onclick="closeOp()">Cancelar</button><button class="btn primary" onclick="updateBasicOperation('${esc(o.id)}')">Guardar cambios</button></div>`;
 setSelectValue('fEntity',o.entity);document.getElementById('opBackdrop').classList.add('open')
}
window.openBasicOperation=openBasicOperation;
async function updateBasicOperation(id){
 try{
  const o=state.operations.find(x=>x.id===id&&x.type!=='Traspaso');if(!o)throw new Error('Operación no encontrada.');
  const type=document.getElementById('fEditType').value,entity=document.getElementById('fEntity').value,isin=document.getElementById('fIsin').value.trim().toUpperCase(),date=document.getElementById('fDate').value,amount=+document.getElementById('fAmount').value||0,shares=+document.getElementById('fShares').value||0;
  if(!isin||!shares||!date)throw new Error('Introduce ISIN, fecha y participaciones.');
  try{await resolveFund(isin,false)}catch{await ensureFund(isin,state.funds[isin]?.name||meta({isin:o.isin}).name||isin,'Sin clasificar')}
  const account=await ensureAccount(entity);
  const typeMap={'Posición inicial':'initial','Compra':'buy','Aportación':'contribution','Reembolso':'redemption','Venta':'sale'};
  const isOut=['Reembolso','Venta'].includes(type);const delta=isOut?-Math.abs(shares):Math.abs(shares);const nav=shares?amount/Math.abs(shares):null;
  await patch('operations',`id=eq.${encodeURIComponent(id)}`,{account_id:account.id,isin,operation_type:typeMap[type],operation_date:date,amount,shares_delta:delta,nav,external_cashflow:isOut?-amount:amount,status:'completed'});
  closeOp();await syncFromCloud();navigate('operations');
 }catch(err){alert('No se pudo actualizar la operación: '+err.message)}
}
window.updateBasicOperation=updateBasicOperation;

function setSelectValue(id,value){const el=document.getElementById(id);if(el)el.value=value}
function openPendingTransfer(id){const o=state.operations.find(x=>x.id===id&&x.type==='Traspaso');if(!o)return;document.getElementById('opContent').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">Traspaso pendiente</div><div class="drawer-title">Completar operación</div></div><button class="close" onclick="closeOp()">×</button></div><div class="op-flow" style="margin:16px 0"><div class="op-box"><strong>${entityWordmark(o.fromEntity)}</strong>${esc(meta({isin:o.from}).name)}</div><div>→</div><div class="op-box"><strong>${entityWordmark(o.toEntity)}</strong>${esc(meta({isin:o.to}).name)}</div></div><div class="form-grid"><div class="field"><label>Entidad origen</label><select id="fFromEntity">${entityOptions()}</select></div><div class="field"><label>ISIN origen</label><input id="fFromIsin" value="${esc(o.from)}" /></div><div class="field"><label>Entidad destino</label><select id="fToEntity">${entityOptions()}</select></div><div class="field"><label>ISIN destino</label><input id="fToIsin" value="${esc(o.to)}" /></div><div class="field"><label>Fecha</label><input id="fDate" type="date" value="${esc(o.date)}" /></div><div class="field"><label>Importe</label><input id="fAmount" type="number" inputmode="decimal" step="any" value="${o.amount||''}" /></div><div class="field"><label>Participaciones de salida</label><input id="fFromShares" type="number" inputmode="decimal" step="any" value="${o.fromShares??''}" /></div><div class="field"><label>Participaciones de entrada</label><input id="fToShares" type="number" inputmode="decimal" step="any" value="${o.toShares??''}" /></div><div class="notice">Puedes guardar datos parciales. Al completar ambas participaciones el traspaso se finalizará y actualizará las posiciones.</div></div><div class="form-actions"><button class="btn" onclick="closeOp()">Cancelar</button><button class="btn primary" onclick="updatePendingTransfer('${esc(o.id)}')">Guardar cambios</button></div>`;setSelectValue('fFromEntity',o.fromEntity);setSelectValue('fToEntity',o.toEntity);document.getElementById('opBackdrop').classList.add('open')}
window.openPendingTransfer=openPendingTransfer;
async function updatePendingTransfer(id){
 try{const fromEntity=document.getElementById('fFromEntity').value,toEntity=document.getElementById('fToEntity').value,from=document.getElementById('fFromIsin').value.trim().toUpperCase(),to=document.getElementById('fToIsin').value.trim().toUpperCase(),date=document.getElementById('fDate').value,amount=+document.getElementById('fAmount').value||0,fromShares=+document.getElementById('fFromShares').value||null,toShares=+document.getElementById('fToShares').value||null;try{await resolveFund(from,false)}catch{await ensureFund(from,state.funds[from]?.name||from,'Sin clasificar')}try{await resolveFund(to,false)}catch{await ensureFund(to,state.funds[to]?.name||to,'Sin clasificar')}const a=await ensureAccount(fromEntity),b=await ensureAccount(toEntity);await patch('transfers',`id=eq.${encodeURIComponent(id)}`,{from_account_id:a.id,from_isin:from,to_account_id:b.id,to_isin:to,request_date:date,amount,shares_out:fromShares,shares_in:toShares,status:'pending'});if(fromShares&&toShares)await rpc('complete_transfer',{p_transfer_id:id,p_shares_out:fromShares,p_shares_in:toShares,p_settlement_date:date,p_nav_out:amount/fromShares||null,p_nav_in:amount/toShares||null});closeOp();await syncFromCloud();navigate('operations')}
 catch(err){alert('No se pudo actualizar el traspaso: '+err.message)}
}
window.updatePendingTransfer=updatePendingTransfer;

async function refreshPortfolio(){state.lastValue=total();saveCache();await syncFromCloud(true)}
function exportBackup(){const payload={app:'Mi Cartera',appVersion:APP_VERSION,schemaVersion:DATA_SCHEMA_VERSION,exportedAt:new Date().toISOString(),cloudProject:SUPABASE_URL,state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`mi-cartera-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
window.exportBackup=exportBackup;

function toggleTheme(){const root=document.documentElement;root.dataset.theme=root.dataset.theme==='dark'?'':'dark';localStorage.setItem(THEME_KEY,root.dataset.theme||'light');setTimeout(()=>{const c=document.getElementById('fundChart');if(c){const p=state.positions.find(x=>document.getElementById('detailBackdrop').classList.contains('open')&&document.getElementById('detailContent').textContent.includes(meta(x).name));if(p)drawChart(p,'M3')}},30)}

async function init(){
 if(!SUPABASE_URL||!SUPABASE_KEY){showAuth();setAuthMessage('Configuración de Supabase incompleta.',true);return}
 loadCache();renderAll();const ok=await ensureSession();if(!ok){showAuth();return}showApp();await syncFromCloud();
}

